  function reload(){if(!running||paused||reloadUntil||ammo===30||reserve<=0)return;reloadUntil=performance.now()+1500;sound('reload');$('reload-indicator').classList.remove('hidden');$('reload-fill').style.transition='none';$('reload-fill').style.width='0';requestAnimationFrame(()=>{$('reload-fill').style.transition='width 1.5s linear';$('reload-fill').style.width='100%'})}
