  }
  function finish(win){if(finished)return;finished=true;running=false;paused=false;document.exitPointerLock?.();$('result-screen').classList.remove('hidden');$('result-kicker').textContent=win?'MISSION COMPLETE':'OPERATOR DOWN';$('result-title').innerHTML=win?'AREA<br/><span>SECURED.</span>':'MISSION<br/><span>FAILED.</span>';$('result-copy').textContent=win?'Hostile presence neutralized. Good work, operator.':'You were overwhelmed in the field. Regroup and redeploy.';$('result-kills').textContent=String(kills).padStart(2,'0');$('result-accuracy').textContent=shots?Math.round(hits/shots*100)+'%':'—';$('result-time').textContent=formatTime((performance.now()-gameStart)/1000)}
  function formatTime(seconds){const s=Math.floor(seconds);return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
