  function resume(){paused=false;running=true;$('pause-screen').classList.add('hidden');$('view').requestPointerLock?.()}
  let touchMove={x:0,y:0},joystickPointer=null,lastTouchX=0,lastTouchY=0;
  function loop(now){const dt=Math.min(.05,(now-(lastTime||now))/1000);lastTime=now;update(dt,now);render(now);requestAnimationFrame(loop)}
  setMap(0);running=false;requestAnimationFrame(loop);
  $('next-map').addEventListener('click',()=>setMap(mapIndex+1));
  $('deploy-button').addEventListener('click',()=>{resetGame();$('view').requestPointerLock?.()});
