  $('resume-button').addEventListener('click',resume);
  $('restart-button').addEventListener('click',()=>{resetGame();$('view').requestPointerLock?.()});
  $('again-button').addEventListener('click',()=>{resetGame();$('view').requestPointerLock?.()});
  $('change-map-button').addEventListener('click',()=>{$('result-screen').classList.add('hidden');$('start-screen').classList.remove('hidden');setMap(mapIndex+1);running=false});
  $('view').addEventListener('click',()=>{if(running&&!paused){shoot();if(!document.pointerLockElement)$('view').requestPointerLock?.()}});
  document.addEventListener('pointerlockchange',()=>{});
  document.addEventListener('mousemove',e=>{if(running&&!paused){if(document.pointerLockElement===view){player.a=norm(player.a+e.movementX*.0022)}else if(e.buttons===1&&e.clientX>120){player.a=norm(player.a+e.movementX*.003)}}});
  document.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.code==='KeyR')reload();if(e.code==='Escape'&&running)pause();if(e.code==='Enter'&&paused)resume()});
  document.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>keys.clear());
  $('view').addEventListener('touchstart',e=>{if(!running)return;const t=e.changedTouches[0];lastTouchX=t.clientX;lastTouchY=t.clientY},{passive:true});
  $('view').addEventListener('touchmove',e=>{if(!running||paused)return;const t=e.changedTouches[0],dx=t.clientX-lastTouchX;player.a=norm(player.a+dx*.008);lastTouchX=t.clientX;lastTouchY=t.clientY},{passive:true});
  const joy=$('joystick'),stick=$('stick');joy.addEventListener('pointerdown',e=>{joystickPointer=e.pointerId;joy.setPointerCapture(e.pointerId);joyMove(e)});joy.addEventListener('pointermove',e=>{if(joystickPointer===e.pointerId)joyMove(e)});joy.addEventListener('pointerup',e=>{if(joystickPointer===e.pointerId){joystickPointer=null;touchMove={x:0,y:0};stick.style.transform='translate(0,0)'}});joy.addEventListener('pointercancel',()=>{joystickPointer=null;touchMove={x:0,y:0};stick.style.transform='translate(0,0)'});
  function joyMove(e){const r=joy.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=clamp(e.clientX-cx,-34,34),dy=clamp(e.clientY-cy,-34,34);touchMove={x:dx/34,y:dy/34};stick.style.transform=`translate(${dx}px,${dy}px)`}
  $('mobile-fire').addEventListener('pointerdown',e=>{e.preventDefault();keys.add('Space');shoot()});['pointerup','pointercancel','pointerleave'].forEach(ev=>$('mobile-fire').addEventListener(ev,()=>keys.delete('Space')));
  $('mobile-reload').addEventListener('pointerdown',e=>{e.preventDefault();reload()});
})();

