const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox']});
 const page=await browser.newPage({viewport:{width:1440,height:900}});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
 await page.goto('http://127.0.0.1:3002');await page.waitForTimeout(500);
 console.log('initial',await page.title(),await page.locator('#selected-map-name').textContent());
 for(let i=0;i<3;i++){await page.locator('#next-map').click();console.log('map',i,await page.locator('#selected-map-name').textContent())}
 await page.locator('#deploy-button').click();await page.waitForTimeout(250);
 console.log('deployed',await page.locator('#objective-count').textContent(),'ammo',await page.locator('#ammo-value').textContent());
 await page.mouse.click(720,450);await page.waitForTimeout(100);
 console.log('fired ammo',await page.locator('#ammo-value').textContent());
 await page.keyboard.press('r');console.log('reload visible',await page.locator('#reload-indicator').evaluate(el=>!el.classList.contains('hidden')));await page.waitForTimeout(1600);
 console.log('reloaded ammo',await page.locator('#ammo-value').textContent());
 await page.locator('#pause-button').click();console.log('paused',await page.locator('#pause-screen').evaluate(el=>!el.classList.contains('hidden')));
 await page.locator('#resume-button').click();console.log('resumed',await page.locator('#pause-screen').evaluate(el=>el.classList.contains('hidden')));
 await page.screenshot({path:'/tmp/opencode-fieldops-tested.png'});
 console.log('errors',errors);
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

