content.text:
.topbar{position:absolute;z-index:4;top:0;left:0;right:0;height:68px;padding:0 36px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(228,230,212,.14);background:linear-gradient(180deg,rgba(9,12,9,.56),transparent)}
.icon-button{width:34px;height:34px;border:1px solid #ffffff3b;background:#141812a6;font-size:15px}
.hud{position:absolute;inset:0;z-index:3;pointer-events:none}
.lower-hud{position:absolute;bottom:28px;left:36px;right:36px;display:flex;align-items:end;justify-content:space-between}
.hud-icon{font:32px var(--body);font-weight:700;color:var(--acid);line-height:1}
.start-screen,.pause-screen,.result-screen{position:absolute;inset:0;z-index:6;background:linear-gradient(90deg,rgba(11,14,10,.94) 0%,rgba(12,15,11,.83) 35%,rgba(12,15,11,.22) 70%,rgba(12,15,11,.1));display:flex;align-items:center;padding:0 clamp(28px,10.2vw,160px)}
.start-panel>.eyebrow,.pause-card>.eyebrow{display:flex;align-items:center;gap:11px;font-size:8px;letter-spacing:1.4px;color:#b4b8aa}
.start-screen.hidden,.pause-screen.hidden,.result-screen.hidden,.hidden{display:none!important}
.pause-screen,.result-screen{justify-content:center;background:rgba(9,12,9,.75);backdrop-filter:blur(8px)}
.pause-card,.result-card{width:min(430px,90vw);border:1px solid #e3e7d52b;background:rgba(18,22,17,.92);padding:38px}
.pause-card h2,.result-card h2{font:900 57px/.82 var(--display);margin:29px 0 17px;letter-spacing:.5px}
.pause-card h2 span,.result-card h2 span{color:var(--acid)}
.pause-card p,.result-card p{color:#aaaea0;font-size:14px}
.mobile-controls{display:none;position:absolute;z-index:5;inset:auto 0 20px;align-items:end;justify-content:space-between;padding:0 22px;pointer-events:none}

