const fs = require('fs');
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const source = fs.readFileSync('/home/runner/work/PlayGround/PlayGround/game.js', 'utf8');
  const instrumented = source.replace(/\}\)\(\);\s*$/, "window.__fieldOpsTest={finish,takeDamage,setStats:(k,s,h)=>{kills=k;shots=s;hits=h}};})();");
  const errors = [];
  for (const outcome of ['victory', 'failure']) {
    const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
    page.on('pageerror', error => errors.push(error.message));
    await page.route('**/game.js', route => route.fulfill({ contentType: 'application/javascript', body: instrumented }));
    await page.goto('http://127.0.0.1:3002');
    await page.locator('#deploy-button').click();
    if (outcome === 'victory') {
      await page.evaluate(() => { window.__fieldOpsTest.setStats(5, 10, 8); window.__fieldOpsTest.finish(true); });
      const details = await page.locator('#result-screen').evaluate(el => ({ visible: !el.classList.contains('hidden'), kicker: document.querySelector('#result-kicker').textContent, title: document.querySelector('#result-title').innerText, kills: document.querySelector('#result-kills').textContent, accuracy: document.querySelector('#result-accuracy').textContent }));
      console.log('victory result:', JSON.stringify(details));
      if (!details.visible || details.kicker !== 'MISSION COMPLETE' || details.kills !== '05' || details.accuracy !== '80%') throw new Error('Victory screen assertion failed');
      await page.locator('#again-button').click();
      console.log('victory restart:', await page.locator('#result-screen').evaluate(el => el.classList.contains('hidden')), await page.locator('#objective-count').textContent());
      if (!(await page.locator('#result-screen').evaluate(el => el.classList.contains('hidden')))) throw new Error('Run again did not restart');
    } else {
      await page.evaluate(() => { window.__fieldOpsTest.setStats(2, 4, 1); window.__fieldOpsTest.takeDamage(100); });
      const details = await page.locator('#result-screen').evaluate(el => ({ visible: !el.classList.contains('hidden'), kicker: document.querySelector('#result-kicker').textContent, title: document.querySelector('#result-title').innerText, kills: document.querySelector('#result-kills').textContent, accuracy: document.querySelector('#result-accuracy').textContent }));
      console.log('operator-down result:', JSON.stringify(details));
      if (!details.visible || details.kicker !== 'OPERATOR DOWN' || details.kills !== '02' || details.accuracy !== '25%') throw new Error('Failure screen assertion failed');
      await page.locator('#change-map-button').click();
      console.log('change operation:', await page.locator('#start-screen').evaluate(el => !el.classList.contains('hidden')), await page.locator('#selected-map-name').textContent());
      if (!(await page.locator('#start-screen').evaluate(el => !el.classList.contains('hidden')))) throw new Error('Change operation did not return to selection');
